   "innerHTML": " <!-- Footer Bottom Border -->\n    <footer class=\"footer-bottom\">\n        <div class=\"footer-blue-bg\"></div>\n        <div class=\"footer-stripe footer-stripe-1\"></div>\n        <div class=\"footer-stripe footer-stripe-2\"></div>\n    </footer>\n\n<style>/* Footer Bottom Border */\n        .footer-bottom {\n            position: relative;\n            width: 100%;\n            height: 48px;\n            background: #f5f5f5;\n            overflow: hidden;\n        }\n\n        /* The main blue background block */\n        .footer-blue-bg {\n            position: absolute;\n            top: 0;\n            bottom: 0;\n            left: -100px;\n            /* Extend past left edge to cover skew gap */\n            right: 58px;\n            /* Position where the main blue block ends */\n            background: #1d2b5c;\n            /* Deep navy blue matching the image */\n            transform: skewX(-35deg);\n            transform-origin: top;\n            transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.5s ease;\n            animation: slideInBg 1.2s cubic-bezier(0.16, 1, 0.3, 1) both;\n        }\n\n        /* The parallel blue stripes */\n        .footer-stripe {\n            position: absolute;\n            top: 0;\n            bottom: 0;\n            width: 6px;\n            /* Width of the diagonal stripes */\n            background: #1d2b5c;\n            transform: skewX(-35deg);\n            transform-origin: top;\n            transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.5s ease, filter 0.5s ease;\n        }\n\n        .footer-stripe-1 {\n            right: 44px;\n            animation: slideInStripe 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.4s both;\n        }\n\n        .footer-stripe-2 {\n            right: 30px;\n            animation: slideInStripe 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.6s both;\n        }\n\n        /* Interactive Hover Effects */\n        .footer-bottom:hover .footer-blue-bg {\n            background-color: #2b3d80; /* Brighter/richer blue on hover */\n            transform: skewX(-35deg) scaleX(1.01);\n        }\n\n        .footer-bottom:hover .footer-stripe {\n            background-color: #2b3d80;\n            filter: drop-shadow(0 0 4px rgba(43, 61, 128, 0.6));\n        }\n\n        .footer-bottom:hover .footer-stripe-1 {\n            transform: skewX(-35deg) translateX(4px);\n        }\n\n        .footer-bottom:hover .footer-stripe-2 {\n            transform: skewX(-35deg) translateX(8px);\n        }\n\n        /* Animations */\n        @keyframes slideInBg {\n            from {\n                transform: skewX(-35deg) translateX(-100%);\n            }\n            to {\n                transform: skewX(-35deg) translateX(0);\n            }\n        }\n\n        @keyframes slideInStripe {\n            from {\n                transform: skewX(-35deg) translateX(50px);\n                opacity: 0;\n            }\n            to {\n                transform: skewX(-35deg) translateX(0);\n                opacity: 1;\n            }\n        }\n\n        /* Responsive adjustments */\n        @media (max-width: 768px) {\n            .footer-bottom {\n                height: 40px;\n            }\n\n            .footer-blue-bg {\n                right: 42px;\n            }\n\n            .footer-stripe {\n                width: 4.5px;\n            }\n\n            .footer-stripe-1 {\n                right: 32px;\n            }\n\n            .footer-stripe-2 {\n                right: 22px;\n            }\n        }</style>",
